// templ: type-safe Go templates (github.com/a-h/templ) serving the same page. page_templ.go is generated by `templ generate`.
package main

import (
	"encoding/json"
	"flag"
	"log"
	"net/http"
	"os"
)

type Product struct {
	ID, Title, Brand, Desc string
	Price                  int
	Tags                   []string
	Rating                 float64
}

func main() {
	addr := flag.String("addr", ":3003", "")
	flag.Parse()
	b, err := os.ReadFile("../data/products.json")
	if err != nil {
		log.Fatal(err)
	}
	var items []Product
	json.Unmarshal(b, &items)
	css, _ := os.ReadFile("../shared.css")
	page := Page(items, string(css))
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		page.Render(r.Context(), w)
	})
	http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("ok")) })
	log.Fatal(http.ListenAndServe(*addr, nil))
}
